import { readFileSync } from "fs";

const s = readFileSync(0, "utf8").trim();

const parts: string[] = [];
let i = 0;
while (i < s.length) {
  // 同じ文字が続く限り j を進める
  let j = i;
  while (j < s.length && s[j] === s[i]) j++;
  parts.push(s[i] + (j - i));
  i = j;
}
console.log(parts.join(""));
